use vstd::prelude::*;
use vstd::vec::Vec;

verus! {
    /// Given a non-empty vector of i8, returns the index of the first occurrence
    /// of the maximum element.
    fn nanargmax(a: Vec<i8>) -> usize
        requires
            a.len() > 0,
        ensures
            // result is a valid index
            result < a.len(),
        ensures
            // a[result] is >= every element in a
            forall |j: usize| j < a.len() ==> a[result] >= a[j],
        ensures
            // if any a[j] == a[result], then result is the smallest such j
            forall |j: usize| j < a.len() && a[j] == a[result] ==> result <= j,
    {
        // We keep:
        //   `idx` = index of the best (max, earliest) value seen so far,
        //   `max_val` = a[idx],
        //   and we scan `i` from 1..a.len().
        let mut idx: usize = 0;
        let mut max_val: i8 = a[0];
        let mut i: usize = 1;
        while i < a.len() {
            invariant
                1 <= i && i <= a.len(),
            invariant
                // idx points to the best in [0, i)
                idx < i,
            invariant
                // for all processed positions j < i, a[idx] >= a[j]
                forall |j: usize| j < i ==> a[idx] >= a[j],
            invariant
                // among j < i with a[j] == a[idx], idx is smallest
                forall |j: usize| j < i && a[j] == a[idx] ==> idx <= j,
            decreases
                a.len() - i,
            {
                let ai = a[i];
                if ai > max_val {
                    max_val = ai;
                    idx = i;
                }
                // if ai == max_val then idx already points to the earlier occurrence,
                // so we do nothing
                i += 1;
            }
        }
        idx
    }
}    

